data.to:
app.get('/users', async (req, res) => {
  try {
    const users = await db.query('SELECT * FROM users')
    const filtered = users.filter(u => u.active)
    const mapped = filtered.map(u => ({
      ...u, role: u.role || 'user'
    }))
    res.json(mapped)
  } catch (e) {
    res.status(500).json({ error: 'fail' })
  }
})

